// MIDDLEWARE — attached per request ("Unary with middleware"), and run AFTER the
// body and metadata have been evaluated, on the already-serialised JSON message.
// It receives the outgoing ctx and returns the ctx to send; returning nothing
// keeps the ctx unchanged. Chained middleware runs in the order it is attached.
//
// Unlike a request body, a middleware cannot call this collection's generators —
// only the body/metadata path composes them in.

type Ctx = {
  body: Record<string, unknown>;
  metadata: Record<string, string>;
  target: string;
};

export function handle(ctx: Ctx): Ctx {
  return {
    ...ctx,
    metadata: {
      ...ctx.metadata,
      "x-trace-id": Math.random().toString(36).slice(2, 10),
      "x-body-bytes": String(JSON.stringify(ctx.body).length),
    },
    body: { ...ctx.body, message: `[traced] ${ctx.body.message ?? ""}` },
  };
}
